const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const season_no = Number(raw.season_no || raw.season_number || raw.current_season || 1);

const rawIntent = (raw.intent || raw.downstream_command || 'TRANSITION_STATE').toString().toUpperCase().trim();
const fsm_intent = (rawIntent === 'RESOLVE_DEADLOCKS' || rawIntent === 'SWEEP_ZOMBIES') ? 'RESOLVE_DEADLOCKS' : 'TRANSITION_STATE';

const target_state = (raw.target_state || raw.payload?.target_state || (rawIntent === 'GENERATE_EPISODE' ? 'GENERATING' : 'GENERATING')).toString().toUpperCase().trim();

const timeoutHours = Number($env.DEADLOCK_TIMEOUT_HOURS || 3);
const timeoutMs = timeoutHours * 3600 * 1000;
const cutoff_timestamp_iso = new Date(Date.now() - timeoutMs).toISOString();

if (!project_id && fsm_intent === 'TRANSITION_STATE') {
  throw new Error('WF-10 Error: project_id is strictly required for State Transitions (Rule 5).');
}

return {
  json: {
    ...raw, project_id, episode_no, episode_number: episode_no, season_no, season_number: season_no,
    fsm_intent, target_state, timeout_hours: timeoutHours, cutoff_timestamp_iso, payload: raw.payload || {},
    sessionId: (raw.sessionId || `sess_${$execution.id}`).toString()
  }
};

const base = $('Input Normalizer & Timeout Resolver').item.json;
const resp = $input.item.json;
const existingRecord = Array.isArray(resp) ? resp[0] : (resp && resp.current_state ? resp : null);
const current_state = (existingRecord?.current_state || 'PENDING').toString().toUpperCase().trim();
const target_state = base.target_state;

const TRANSITION_MATRIX = {
  PENDING: ['GENERATING'],
  QUEUED: ['GENERATING'],
  GENERATING: ['SCENE_PLAN_READY', 'FAILED'],
  SCENE_PLAN_READY: ['PRODUCTION', 'FAILED'],
  PRODUCTION: ['MIXED', 'FAILED'],
  MIXED: ['QC_APPROVED', 'FAILED'],
  QC_APPROVED: ['PUBLISHED', 'FAILED'],
  PUBLISHED: [],
  FAILED: ['PENDING', 'QUEUED', 'GENERATING']
};

const allowedNextStates = TRANSITION_MATRIX[current_state] || [];
const isSameStateIdempotent = current_state === target_state;
const isTransitionAllowed = allowedNextStates.includes(target_state) || isSameStateIdempotent;

if (!isTransitionAllowed) {
  return {
    json: {
      ...base, previous_state: current_state, transition_valid: false, error_code: 'ERR_RULE_50_INVALID_STATE_TRANSITION',
      error_message: `Rule 50 State Machine Violation: Invalid jump from '${current_state}' to '${target_state}' for Episode ${base.episode_no}. Allowed next states from '${current_state}': [${allowedNextStates.join(', ') || 'NONE (Terminal)'}].`
    }
  };
}

const nowIso = $now.toISOString();
return {
  json: {
    ...base, previous_state: current_state, transition_valid: true, updated_at: nowIso,
    state_patch_payload: { project_id: base.project_id, episode_no: base.episode_no, current_state: target_state, last_state_change_at: nowIso, updated_at: nowIso }
  }
};

const base = $('Input Normalizer & Timeout Resolver').item.json;
const rawItems = $input.all().map(i => i.json);
const nowMs = Date.now();
const timeoutMs = Number(base.timeout_hours || 3) * 3600 * 1000;
const zombieRows = [];

for (const entry of rawItems) {
  if (Array.isArray(entry)) { for (const r of entry) { if (r && r.current_state) zombieRows.push(r); } }
  else if (entry && entry.current_state) { zombieRows.push(entry); }
}

const verifiedZombies = zombieRows.filter(z => {
  if (!z.updated_at) return true;
  const deltaMs = nowMs - new Date(z.updated_at).getTime();
  return deltaMs > timeoutMs;
});

const unlockTargetState = ($env.DEADLOCK_UNLOCK_STATE || 'FAILED').toString().toUpperCase().trim();
const nowIso = $now.toISOString();

const pendingActionNotifications = verifiedZombies.map(z => ({
  project_id: z.project_id || base.project_id, action_type: 'DEADLOCK_SWEEPER_UNLOCK', review_type: 'ZOMBIE_JOB_REVERTED', status: 'MANUAL_REVIEW',
  action_payload: { episode_no: z.episode_no, stuck_state: z.current_state, last_updated_at: z.updated_at, reverted_to: unlockTargetState, swept_at: nowIso }
}));

return { json: { ...base, zombie_count: verifiedZombies.length, verified_zombies: verifiedZombies, unlock_target_state: unlockTargetState, swept_at: nowIso, pending_notifications_batch: pendingActionNotifications } };

const base = $('Input Normalizer & Timeout Resolver').item.json;

if (base.fsm_intent === 'RESOLVE_DEADLOCKS') {
  const sweep = $('Zombie Job Sweeper Evaluator').item.json;
  const zombieList = sweep.verified_zombies.length > 0 ? sweep.verified_zombies.map(z => `• Project \`${z.project_id}\` Ep ${z.episode_no}: Stuck in \`${z.current_state}\` since \`${z.updated_at}\` -> Reverted to \`${sweep.unlock_target_state}\``).join('\n') : `• Koi bhi zombie job (> ${sweep.timeout_hours} hours stuck in GENERATING/PRODUCTION) nahi mila.`;

  const sweepMsg = [
    `🧹 **WF-10: Section 62 Deadlock / Zombie Sweeper Complete!**`,
    `• **Timeout Threshold:** > ${sweep.timeout_hours} Hours (\`cutoff: ${sweep.cutoff_timestamp_iso}\`)`,
    `• **Zombie Jobs Unlocked:** ${sweep.zombie_count}`, zombieList
  ].join('\n');

  return { json: { ...base, ok: true, status: 'DEADLOCK_SWEEP_COMPLETED', workflow_name: 'WF-10', execution_id: $execution.id, zombie_count: sweep.zombie_count, unlocked_jobs: sweep.verified_zombies, output: sweepMsg, text: sweepMsg } };
}

const guard = $('Transactional Matrix Guard (Rule 50)').item.json;

if (guard.transition_valid === false) {
  const errMsg = [
    `🛑 **WF-10: Rule 50 State Transition Blocked!**`,
    `• **Episode:** ${guard.episode_no} | **Attempted Jump:** \`${guard.previous_state} -> ${guard.target_state}\``,
    `• **Error:** ${guard.error_message}`
  ].join('\n');
  return { json: { ...base, ok: false, status: 'ERR_INVALID_STATE_TRANSITION', workflow_name: 'WF-10', execution_id: $execution.id, previous_state: guard.previous_state, target_state: guard.target_state, error_code: guard.error_code, output: errMsg, text: errMsg } };
}

const okMsg = [
  `⚙️ **WF-10: Rule 50 State Transition Committed!**`,
  `• **Project ID:** \`${guard.project_id}\` | **Episode:** ${guard.episode_no}`,
  `• **Transition:** \`${guard.previous_state} -> ${guard.target_state}\` (\`${guard.updated_at}\`)`
].join('\n');

return { json: { ...base, ok: true, status: 'STATE_TRANSITION_COMMITTED', workflow_name: 'WF-10', execution_id: $execution.id, previous_state: guard.previous_state, current_state: guard.target_state, updated_at: guard.updated_at, output: okMsg, text: okMsg } };

